from typing import Any

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)

    plan = fields.String(load_default="free")
    age = fields.Integer(load_default=None, allow_none=True)

    @validates("plan")
    def _validate_plan(self, value: str) -> None:
        allowed = {"free", "pro", "team"}
        if value not in allowed:
            raise ValidationError(f"Plan must be one of: {', '.join(sorted(allowed))}.")

    @validates("username")
    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("age")
    def _validate_age(self, value: int) -> None:
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120 inclusive.")


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup payload.

    Required:
      - username: alphanumeric string
      - email: valid email address

    Optional:
      - plan: default "free", must be one of {"free", "pro", "team"}
      - age: integer in [16, 120]

    Unknown keys are dropped.

    Returns the cleaned dict (default plan included).
    On invalid input, raises ValueError with .messages as {field: [messages...]}.
    """

    class SignupError(ValueError):
        def __init__(self, messages: dict[str, list[str]]):
            super().__init__("invalid signup data")
            self.messages = messages

    try:
        cleaned: dict[str, Any] = _SignupSchema().load(data)
        # Ensure plan default is present even if age/other keys absent (marshmallow handles this).
        return cleaned
    except ValidationError as err:
        # marshmallow uses lists of messages per field
        raise SignupError(err.messages) from None

from __future__ import annotations

from typing import Dict

from importlib import metadata as importlib_metadata


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each distribution name (exactly as provided in `names`) to its installed
    version string, or None if the distribution is not installed.

    Matching is case-insensitive (as per importlib.metadata behavior).
    """
    # Cache lookups to avoid repeated metadata queries.
    # Keyed by the normalized (lowercased) distribution name.
    cache: Dict[str, str | None] = {}

    def _get_version(dist_name: str) -> str | None:
        key = dist_name.lower()
        if key in cache:
            return cache[key]
        try:
            version = importlib_metadata.version(dist_name)
        except importlib_metadata.PackageNotFoundError:
            version = None
        cache[key] = version
        return version

    return {original_name: _get_version(original_name) for original_name in names}
